    failed.add(key);
    errors.push(key + ': read ' + e);
    post({ type: 'log', text: 'SW READ_FAILED ' + key + ' ' + (range || 'whole') + ': ' + e + ' (from the network from now on)' });
    caches.open(CACHE).then((c) => deleteCached(c, key)).catch(() => {});
